<form method="post" action="/admin/training/proposals" class="training-proposal-form"><input type="hidden" name="csrf" value="<?= $h($_SESSION['csrf']) ?>"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label>Titre<input name="title" required maxlength="160" value="<?= $h($edit['title']??'') ?>"></label><label>Besoin à résoudre<textarea name="description" rows="3" required maxlength="6000"><?= $h($edit['description']??'') ?></textarea></label><div class="training-form-grid"><label>Bénéfice pour le client<textarea name="benefit" rows="3" required maxlength="1000"><?= $h($edit['benefit']??'') ?></textarea></label><label>Périmètre proposé<textarea name="scope" rows="3" required maxlength="2000"><?= $h($edit['scope']??'') ?></textarea></label></div><div class="training-form-grid"><label>Priorité<select name="priority"><?php foreach(\App\Services\ClientTraining::PRIORITIES as $k=>$label): ?><option value="<?= $k ?>" <?= ($edit['priority']??'normal')===$k?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>Statut<select name="status"><?php foreach(\App\Services\ClientTraining::STATUSES as $k=>$label): ?><option value="<?= $k ?>" <?= ($edit['status']??'proposed')===$k?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>Budget indicatif (FCFA)<input name="budget" type="number" min="0" max="1000000000" value="<?= $h($edit['budget']??'') ?>" placeholder="À définir"></label><label>Délai indicatif<input name="timeframe" maxlength="160" value="<?= $h($edit['timeframe']??'') ?>" placeholder="À définir"></label></div><button class="admin-button">Enregistrer la proposition</button></form>
